def totals(csv_text):
    # Sum Decimal amounts per name and return string totals with two decimal places.
    # Handle quoted comma-containing names and blank input.
    totals = {}
    lines = csv_text.strip().splitlines()
    if not lines:
        return totals
    header = lines[0]
    # Header must be a CSV header with column names: name,amount.
    if header != "name,amount":
        return totals
    i = 1
    while i < len(lines):
        row = lines[i]
        parts = row.split(",")
        if len(parts) != 2:
            i += 1
            continue
        name, amount = parts
        total = Decimal(parts[1])
        if name in totals:
            totals[name] = total + totals[name]
        else:
            totals[name] = total
        i += 1
    return totals

